CustomField.formula:
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') &&   TSGCFG__ProdTotalCPCColorLineItem__c   > 0 , 
  TSGCFG__ProdSumofCPCColor__c   / TSGCFG__ProdTotalCPCColorLineItem__c, 
IF( ABS(TSGCFG__ProdTotalColorVolume__c - TSGCFG__Prod_Total_Volume_Includes_Color__c)<>0,  TSGCFG__ProdTotalColorMonthlyCost__c   / ABS(TSGCFG__ProdTotalColorVolume__c - TSGCFG__Prod_Total_Volume_Includes_Color__c), 
IF( TSGCFG__ProdTotalCPCColorLineItem__c > 0,  TSGCFG__ProdSumofCPCColor__c  / TSGCFG__ProdTotalCPCColorLineItem__c, 0 
) 
) 
)
